import{_t as e,at as t,et as n,it as r,n as i,ot as a,rt as o,xt as s}from"./chunks/framework.C5Z6qjff.js";var c=JSON.parse(`{"title":"Erster Administrator","description":"","frontmatter":{"title":"Erster Administrator","covers":{"screens":[],"stories":["US-013","US-015","US-016","US-017"]}},"headers":[],"relativePath":"de/setup/first-administrator.md","filePath":"de/setup/first-administrator.md"}`),l={name:`de/setup/first-administrator.md`};function u(i,c,l,u,d,f){let p=s(`Screenshot`);return e(),o(`div`,null,[c[0]||=r(`<h1 id="erster-administrator" tabindex="-1">Erster Administrator <a class="header-anchor" href="#erster-administrator" aria-label="Permalink to “Erster Administrator”">​</a></h1><p>Eine neue Instanz hat kein Konto. Das erste – das lokale <strong>Systemadmin-Konto</strong> – legst du mit einem einmaligen Setup-Token an, das nur lesen kann, wer Zugriff auf den Server hat. Einen Identity-Provider brauchst du dafür nicht.</p><h2 id="setup-token-lesen" tabindex="-1">Setup-Token lesen <a class="header-anchor" href="#setup-token-lesen" aria-label="Permalink to “Setup-Token lesen”">​</a></h2><p>Solange kein Systemadmin-Konto existiert, schreibt das Backend ein Setup-Token in die Datei <code>/run/oea/setup-token</code> im Container und protokolliert, wo du es findest. Das Token selbst erscheint nie im Log oder in einer API-Antwort:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /run/oea/setup-token</span></span></code></pre></div><p>Die Datei kann nur der OEA-Benutzer im Container lesen; du brauchst also Zugriff auf den Server oder den Container – über das Netzwerk kann niemand das Token abrufen. Das Token ist 24 Stunden gültig. Jeder Start des Backends erzeugt ein neues Token und macht das vorherige ungültig; ist dein Token abgelaufen, starte das Backend neu und lies die Datei noch einmal. Nach einem erfolgreichen Bootstrapping löscht das Backend die Datei.</p><h2 id="systemadmin-konto-anlegen" tabindex="-1">Systemadmin-Konto anlegen <a class="header-anchor" href="#systemadmin-konto-anlegen" aria-label="Permalink to “Systemadmin-Konto anlegen”">​</a></h2><p>Öffne die Setup-Seite <code>/setup</code> der Weboberfläche (die Startseite zeigt <em>Setup required</em>, solange kein Konto existiert) und fülle aus:</p>`,8),a(p,{name:`setup-required`,alt:`Startseite einer neuen Instanz mit dem Hinweis Setup required`}),c[1]||=r(`<table tabindex="0"><thead><tr><th>Feld</th><th>Bedeutung</th></tr></thead><tbody><tr><td>Setup token</td><td>das Token aus der Datei</td></tr><tr><td>Login name</td><td>der Anmeldename des Systemadmin-Kontos</td></tr><tr><td>Password, Repeat password</td><td>12 bis 128 Zeichen</td></tr><tr><td>Instance slug</td><td>kurzer, stabiler Name der Instanz; er wird in externen Referenzen verwendet (<code>urn:oea:&lt;slug&gt;:&lt;id&gt;</code>) und kann später nicht geändert werden</td></tr></tbody></table>`,1),a(p,{name:`setup-form`,alt:`Setup-Formular mit Token, Anmeldename, Passwort und Instance Slug`}),c[2]||=n(`p`,null,[t(`Wähle `),n(`em`,null,`Create system admin account`),t(`. Die Seite bestätigt das Konto und den Instance Slug.`)],-1),a(p,{name:`setup-done`,alt:`Bestätigung des angelegten Systemadmin-Kontos`}),c[3]||=r(`<p>Über die API sendest du dieselben Daten an <code>POST /api/v1/setup</code>; <code>GET /api/v1/setup/status</code> sagt dir, ob das Setup noch aussteht.</p><ul><li>Das Bootstrapping funktioniert genau einmal. Kommen zwei Versuche gleichzeitig, gelingt genau einer. Jeder weitere Versuch wird abgelehnt, und das Token ist nicht mehr gültig; das bestehende Konto bleibt unverändert.</li><li>Ein fehlendes, falsches oder abgelaufenes Token wird abgelehnt, ohne dass ein Konto entsteht.</li><li>Nach 100 falschen Tokens von einer Adresse innerhalb von 10 Minuten wird diese Adresse für 10 Minuten gesperrt: Die Setup-Seite zeigt „Too many failed attempts. Try again in N seconds.“, und das Token wird in dieser Zeit nicht geprüft. Fehlgeschlagene Logins von derselben Adresse zählen zum selben Limit; andere Adressen sind nicht betroffen (siehe <a href="./../administration/operations#rate-limits">Rate Limits</a>).</li><li>Jeder abgeschlossene und jeder abgelehnte Versuch wird im Audit-Trail mit Zeitpunkt, Modus <code>local</code> und Ergebnis festgehalten: <code>system.bootstrapped</code> (Ergebnis <code>success</code>, dem neuen Systemadmin-Konto zugeordnet) und <code>system.bootstrap-rejected</code> (Ergebnis <code>denied</code>, mit dem Grund, zum Beispiel <code>invalid-setup-token</code>, oder <code>throttled</code> für Versuche von einer gesperrten Adresse; viele gesperrte Versuche innerhalb einer Minute werden in einem Eintrag mit ihrer Anzahl zusammengefasst). Weder das Token noch das Passwort werden festgehalten. Mit diesen Einträgen kannst du belegen, wann und wie der erste privilegierte Zugriff auf die Instanz entstanden ist (siehe <a href="./../administration/operations#verify-the-audit-trail">Audit-Trail prüfen</a>).</li></ul><h2 id="setup-phase" tabindex="-1">Die Setup-Phase <a class="header-anchor" href="#setup-phase" aria-label="Permalink to “Die Setup-Phase”">​</a></h2><p>Nach dem Bootstrapping ist die Instanz in ihrer <strong>Setup-Phase</strong>: Das Systemadmin-Konto meldet sich nur mit Anmeldename und Passwort an. Die Setup-Phase endet mit der ersten Aktion, die einer anderen Identität Zugriff gibt – der ersten Identitätsbindung oder IdP-Gruppenzuordnung (siehe <a href="./../administration/identity-providers">Identity-Provider und Personen</a>). Diese Aktion braucht einen zweiten Faktor:</p><ol><li>Melde dich mit dem Systemadmin-Konto an (siehe <a href="./../usage/login">Anmelden</a>).</li><li>Öffne <em>Profile</em> und wähle <em>Set up a second factor</em>, dann <em>Set up authenticator app</em>. Scanne den QR-Code mit deiner Authenticator-App und gib den Code aus der App ein. Die Sitzung ist jetzt mit dem zweiten Faktor bestätigt.</li><li>Lege die erste Identitätsbindung oder Gruppenzuordnung an. Damit endet die Setup-Phase endgültig (Audit-Event <code>system.setup-phase-ended</code>).</li></ol><p>Ab dann braucht jede Anmeldung des Systemadmin-Kontos einen Code der Authenticator-App.</p><div class="warning custom-block"><p class="custom-block-title">Achtung</p><p>Während der Setup-Phase schützen nur das Passwort und die Drosselung der Anmeldeversuche die Instanz. Beende die Setup-Phase, bevor du die Instanz öffentlich erreichbar machst.</p></div><p>Das Systemadmin-Konto administriert die Instanz (Identity-Provider, Personen, Rollen). Es arbeitet nicht mit Architekturinhalten und kann keine Metamodell-Pakete importieren; diese Aufgaben gehören Personen mit den passenden Rollen (Funktionstrennung, siehe <a href="./../administration/roles-and-permissions">Rollen und Berechtigungen</a>).</p>`,8)])}var d=i(l,[[`render`,u]]);export{c as __pageData,d as default};